const test = require('node:test');
const assert = require('node:assert');
const { capitalize, truncate } = require('../src/strings');

test('capitalize', () => assert.equal(capitalize('abc'), 'Abc'));
test('short text unchanged', () => assert.equal(truncate('abc', 5), 'abc'));
test('exact length unchanged', () => assert.equal(truncate('abcde', 5), 'abcde'));
test('cut with ellipsis', () => assert.equal(truncate('abcdef', 5), 'abcd\u2026'));
test('max 1', () => assert.equal(truncate('abc', 1), '\u2026'));
test('emoji not split', () => assert.equal(truncate('\u{1F600}\u{1F600}\u{1F600}', 2), '\u{1F600}\u2026'));
test('bad max', () => assert.throws(() => truncate('a', 0), RangeError));
